/// <summary>
/// PricingAttribute of table <c>METCustTable</c> field CustOperGroupId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(METCustTable, CustOperGroupId))]
internal class METGUPPricingAttributeMETCustTableCustOprGrp extends METGUPPricingAttributeMETCustTable implements GUPIPricingAttribute
{
}

Method.Source:
/// <summary>
/// Get value of the attribute
/// </summary>
/// <param name="_pricingObject">
/// The <c>Common</c> object that will be used to get the table record
/// </param>
/// <returns><c>anytype</c> object</returns>
public anytype getValueOfAttribute(Common _pricingObject)
{
    return this.getTableRecord(_pricingObject).CustOperGroupId;
}

/// <summary>
/// Retuns the name of the attribute
/// </summary>
/// <returns>name of attribute in string</returns>
public str getName()
{
    return fieldPName(METCustTable, CustOperGroupId);
}

/// <summary>
/// Get attribte data type
/// </summary>
/// <returns><c>AttributeDataType</c> object</returns>
public AttributeDataType getDataType()
{
    return AttributeDataType::Text;
}

    /// <summary>
    /// specify the list of values applicable
    /// </summary>
    /// <returns><c>Set</c> object</returns>
    public Set getAllowedValuesWithDescription()
    {
        var ret = new Set(Types::AnyType);

        METCustomerOperationsGroup      metCustomerOperationsGroupLocal;
        METCustTable                    metCustTableLocal;

        while select CustOperGroupId from metCustTableLocal
            group by CustOperGroupId
            join metCustomerOperationsGroupLocal
            group by CustomerOperationsGroup, Description
            where metCustomerOperationsGroupLocal.CustomerOperationsGroup == metCustTableLocal.CustOperGroupId
        {
            GUPPricingAttributeAllowedValuesObject valueObject =
                new GUPPricingAttributeAllowedValuesObject(metCustomerOperationsGroupLocal.CustomerOperationsGroup, metCustomerOperationsGroupLocal.Description);
            ret.add(valueObject);
        }
        
        return ret;
    }

/// <summary>
///Gets the path of the attribute tables
/// </summary>
public GUPPricingAttributeTableFieldPath getPath()
{
    return METConstants::pathNotExist;
}
